{
  "candidate_edge_types": [
    {
      "name": "OBSERVED_CONTENT_CLASSIFIED_INTO_CATEGORY",
      "definition": "Raw content retrieved from an item is interpreted by the agent to determine the item's category and to extract requested structured fields from it.",
      "source_description": "An observation containing the raw content of an item that must be processed.",
      "target_description": "An agent analysis or decision that assigns a category to the item and extracts the requested field values."
    },
    {
      "name": "CATEGORIZATION_DECISION_DRIVES_ITEM_OPERATION",
      "definition": "A prior categorization decision is used to select and execute an operation on the items, applying different handling depending on the assigned category.",
      "source_description": "A decision that determines the category of the processed items.",
      "target_description": "A subsequent action that operates on the items according to their assigned category."
    },
    {
      "name": "PRIOR_EXTRACTION_USED_AS_INPUT",
      "definition": "Values extracted during earlier analysis are directly embedded as inputs into a subsequent operation that produces a new derived artifact.",
      "source_description": "Structured values produced by a prior analysis step.",
      "target_description": "A subsequent action that consumes those values as input to generate a new artifact."
    },
    {
      "name": "GENERATED_ARTIFACT_VERIFIED_BY_INSPECTION",
      "definition": "An artifact produced by an earlier action is subsequently inspected to confirm that its content matches the required result.",
      "source_description": "An artifact produced by an earlier action.",
      "target_description": "A subsequent check that reads the artifact to verify its correctness."
    },
    {
      "name": "INTERMEDIATE_ARTIFACT_REMOVED_AFTER_USE",
      "definition": "Temporary artifacts created during intermediate processing are deleted once they are no longer needed for the final deliverable.",
      "source_description": "A state or decision indicating intermediate processing is finished and temporary artifacts are no longer required.",
      "target_description": "An action that removes the temporary intermediate artifacts."
    }
  ]
}

